## Java (Java 17)

```java
import java.util.*;

public class MajorityElement {
    /**
     * Returns the majority element if present, otherwise throws NoSuchElementException.
     */
    public static int majorityElement(int[] nums) {
        // ---------- 1. Candidate ----------
        Integer candidate = null;
        int count = 0;

        for (int num : nums) {
            if (count == 0) {
                candidate = num;
                count = 1;
            } else if (num == candidate) {
                count++;
            } else {
                count--;
            }
        }

        // ---------- 2. Verification ----------
        if (candidate == null) {
            throw new NoSuchElementException("Array is empty");
        }

        int occurrences = 0;
        for (int num : nums) {
            if (num == candidate) occurrences++;
        }

        if (occurrences > nums.length / 2) {
            return candidate;
        } else {
            throw new NoSuchElementException("No majority element");
        }
    }

    // Demo
    public static void main(String[] args) {
        int[] arr = {1, 2, 1, 1, 3, 1, 1};
        System.out.println(majorityElement(arr)); // 1
    }
}
```

